export const articles: Article[] = [
  { slug: "identity-starts-with-meaning", topic: "identity", title: copy("الهوية تبدأ من المعنى", "Identity starts with meaning"), excerpt: copy("قبل اختيار الشكل، اسأل: ما الذي نريد أن يشعر به الناس ويتذكروه؟", "Before choosing a form, ask what people should feel and remember."), cover: portfolioImages.journalIdentity, alt: copy("تكوين ورقي هندسي عن الهوية البصرية", "Geometric paper composition about visual identity"), readMinutes: 4, sections: [{ heading: copy("الشكل نتيجة لا بداية", "Form is an outcome, not a beginning"), body: copy("الهوية القوية لا تبدأ من لون يعجبنا؛ تبدأ من فكرة يمكن شرحها واختبارها. حين تكون الفكرة واضحة، يصبح من الأسهل اختيار الأشكال والصور والصوت الذي يخدمها.", "A strong identity does not start with a favorite color; it starts with an idea that can be explained and tested. When the idea is clear, it becomes easier to choose forms, imagery, and voice." ) }, { heading: copy("ابنِ قواعد قابلة للحياة", "Build rules that can live"), body: copy("العلامة ليست ملف شعار واحداً. هي مجموعة قرارات صغيرة تساعد كل تطبيق جديد على الانتماء إلى النظام دون أن يبدو نسخة مطابقة من السابق.", "A brand is not a single logo file. It is a set of small decisions that help each new application belong to the system without becoming a clone of the last one.") }] },
  { slug: "arabic-type-and-rhythm", topic: "identity", title: copy("إيقاع الحروف العربية", "The rhythm of Arabic type"), excerpt: copy("كيف نبني هرمية مقروءة حين تتحرك الكلمات في اتجاه مختلف؟", "How do we build readable hierarchy when words flow in a different direction?"), cover: portfolioImages.journalIdentity, alt: copy("ورق وكتل هندسية تلمّح إلى إيقاع طباعي", "Paper and geometric blocks hinting at typographic rhythm"), readMinutes: 5, sections: [{ heading: copy("ابدأ بالقراءة", "Start with reading"), body: copy("المسافات بين السطور والكلمات ليست تفصيلاً تجميلياً. في النص العربي تساعد المساحة الرأسية والوزن المناسب على حفظ إيقاع الجملة من دون تزاحم.", "Space between lines and words is not decoration. In Arabic, vertical rhythm and the right weight help a sentence breathe without crowding." ) }, { heading: copy("اخلط بحذر", "Pair with care"), body: copy("عند المزج بين خط عربي وآخر لاتيني، قارن الارتفاع البصري وكتلة السطر قبل مقارنة شكل الحروف فقط. الانسجام يأتي من النظام العام.", "When pairing Arabic and Latin fonts, compare visual height and line density before comparing letterforms alone. Harmony comes from the whole system.") }] },
  { slug: "a-mark-that-can-adapt", topic: "identity", title: copy("علامة تتكيف مع سياقها", "A mark that adapts to its context"), excerpt: copy("النظام المرن يحافظ على التعرف حتى حين يتغير حجم المساحة.", "A flexible system preserves recognition even when the available space changes."), cover: portfolioImages.journalIdentity, alt: copy("وحدات بصرية هندسية تتكرر بأحجام مختلفة", "Geometric visual modules repeating at varied sizes"), readMinutes: 4, sections: [{ heading: copy("فكر في العائلة", "Think in families"), body: copy("ابدأ بعنصر مركزي، ثم اختبر ما الذي يمكن تبسيطه أو توسيعه. العلامة الصغيرة قد تحتاج رمزاً، بينما المساحة الواسعة تسمح بتكوين أرحب.", "Start with a central element and test what can be simplified or expanded. A small mark may need a symbol, while a wide canvas can support a broader composition.") }, { heading: copy("اختبر قبل التسليم", "Test before delivery"), body: copy("ضع العلامة في سياقات مختلفة: شاشة ضيقة، صورة مزدحمة، وخلفية هادئة. الاختبارات تكشف القواعد الناقصة قبل أن تصبح عادة.", "Place the mark in varied contexts: a narrow screen, a busy image, and a quiet background. Tests reveal missing rules before they become habits.") }] },
  { slug: "constraints-create-direction", topic: "process", title: copy("القيود التي تفتح الطريق", "Constraints that open a path"), excerpt: copy("القيد الواضح يساعد الفريق على التركيز بدلاً من تقليل الطموح.", "A clear constraint helps a team focus rather than lower its ambition."), cover: portfolioImages.journalProcess, alt: copy("دفتر وأدوات على طاولة عمل مضاءة", "Notebook and tools on a sunlit worktable"), readMinutes: 4, sections: [{ heading: copy("سمّ القيد", "Name the constraint"), body: copy("حين يصبح الوقت أو المحتوى أو التقنية معروفاً، نستطيع ترتيب القرارات. المشكلة ليست في وجود حدود؛ المشكلة حين تبقى غير مرئية.", "When time, content, or technology is understood, decisions become easier to order. Limits are not the problem; invisible limits are." ) }, { heading: copy("اجعل الاختبار صغيراً", "Make the test small"), body: copy("جرّب أصغر نسخة من القرار المهم. نموذج قصير قد يكشف أكثر من مجموعة صفحات كاملة لم تُحسم فكرتها.", "Try the smallest version of the important decision. A small prototype can reveal more than a full set of pages built on an unsettled idea.") }] },
  { slug: "a-better-critique", topic: "process", title: copy("نقد تصميم يساعد على التقدم", "A design critique that moves work forward"), excerpt: copy("بدّل «أحب/لا أحب» بسؤال محدد عن الهدف والسياق.", "Replace “I like it / I don't” with a precise question about goal and context."), cover: portfolioImages.journalProcess, alt: copy("أوراق ملاحظات مجردة في تكوين تحريري", "Abstract note papers in an editorial composition"), readMinutes: 5, sections: [{ heading: copy("اربط الملاحظة بالهدف", "Tie feedback to the goal"), body: copy("الملاحظة تصبح قابلة للاستخدام حين توضح ما الذي لاحظته ولماذا قد يؤثر على تجربة الشخص. هذا يفتح مساحة للحلول بدل الدفاع عن اختيار واحد.", "Feedback becomes useful when it states what was noticed and why it may affect someone's experience. That opens room for solutions instead of defending one choice.") }, { heading: copy("اختم بخطوة", "End with a next step"), body: copy("اتفق على تجربة قابلة للمراجعة: مقارنة نسختين، أو اختبار قراءة، أو متابعة ملاحظة واحدة. الخطوة المحددة تحول النقاش إلى تقدم.", "Agree on a reviewable experiment: compare two versions, test readability, or follow one observation. A specific next step turns discussion into progress.") }] },
  { slug: "anatomy-of-a-case-study", topic: "process", title: copy("تشريح دراسة الحالة", "The anatomy of a case study"), excerpt: copy("قصة المشروع الجيدة تشرح القرارات، لا تعرض الصور النهائية فقط.", "A useful case study explains decisions rather than showing final images alone."), cover: portfolioImages.journalProcess, alt: copy("تسلسل صفحات مفاهيمية على طاولة تحريرية", "A sequence of concept pages on an editorial table"), readMinutes: 4, sections: [{ heading: copy("ابدأ بالسؤال", "Start with the question"), body: copy("قدّم المشكلة والسياق والدور بعبارات بسيطة. القارئ يريد فهم سبب وجود المشروع قبل الحكم على تفاصيله البصرية.", "Introduce the problem, context, and role in plain language. Readers want to understand why the project existed before judging its visual details.") }, { heading: copy("اشرح ما تعلمته", "Explain what you learned"), body: copy("اعرض نتيجة يمكن إثباتها، وإن لم تكن هناك بيانات موثوقة فاشرح القرار أو ما ستختبره تالياً. الصراحة جزء من جودة العرض.", "Show an outcome you can support; without trustworthy data, explain the decision or what you would test next. Honesty is part of good presentation.") }] },
  { slug: "empty-states-are-content", topic: "digital-products", title: copy("الحالة الفارغة جزء من التجربة", "Empty states are part of the experience"), excerpt: copy("الفراغ ليس خطأ؛ أحياناً هو أول فرصة لشرح ما يمكن فعله.", "An empty screen is not always an error; it can be the first chance to show what is possible."), cover: portfolioImages.journalDigital, alt: copy("بطاقات واجهة شفافة ومجسم أزرق", "Translucent interface cards and a blue glass form"), readMinutes: 5, sections: [{ heading: copy("قل ماذا حدث", "Explain what happened"), body: copy("قد يكون المستخدم لم يبدأ بعد، أو لم تظهر نتائج بحثه، أو فقد الاتصال. سمِّ الحالة بوضوح بدلاً من عرض مساحة صامتة.", "Someone may not have started yet, search may return nothing, or a connection may be lost. Name the state clearly instead of showing a silent space.") }, { heading: copy("اقترح خطوة آمنة", "Offer a safe next step"), body: copy("الزر الأفضل هو الذي يقود إلى فعل واضح ومتناسب: امسح الفلتر أو أضف أول عنصر أو أعد المحاولة.", "The best action leads to a clear, proportional step: clear a filter, add the first item, or try again.") }] },
  { slug: "making-interfaces-breathe", topic: "digital-products", title: copy("مساحة تنفّس للواجهات", "Give interfaces room to breathe"), excerpt: copy("التسلسل والمسافات يساعدان العين على معرفة أين تبدأ.", "Hierarchy and spacing help the eye know where to begin."), cover: portfolioImages.journalDigital, alt: copy("سطوح واجهة مجردة بظلال ورقية", "Abstract interface surfaces with paper-like shadows"), readMinutes: 4, sections: [{ heading: copy("لا تساوِ بين كل العناصر", "Not every element is equal"), body: copy("حين تتنافس كل البطاقات والعناوين على الانتباه، لا يعود هناك شيء بارز. استخدم الحجم والوزن والمساحة لتوضيح ما يستحق النظر أولاً.", "When every card and headline competes for attention, nothing stands out. Use scale, weight, and space to show what deserves attention first.") }, { heading: copy("اختبر على الشاشة الصغيرة", "Test on the small screen"), body: copy("الترتيب الذي يبدو متوازناً على شاشة واسعة قد يصبح طويلاً على الهاتف. اجعل الأولوية للمعلومة والفعل الأهم.", "A layout that feels balanced on a wide screen may become lengthy on a phone. Prioritize the most important information and action.") }] },
  { slug: "accessible-by-default", topic: "digital-products", title: copy("الوصول يبدأ من القرار الأول", "Accessibility starts with the first decision"), excerpt: copy("العناوين الدلالية والتركيز المرئي ليست إضافات ما بعد التصميم.", "Semantic headings and visible focus are not post-design extras."), cover: portfolioImages.journalDigital, alt: copy("مساحات واجهة واضحة وتباين لوني قوي", "Clear interface surfaces with strong color contrast"), readMinutes: 6, sections: [{ heading: copy("صمّم لكل طرق الاستخدام", "Design for different ways of using"), body: copy("التباين، ترتيب العناوين، الأسماء الواضحة للأزرار، والاختيار بلوحة المفاتيح تجعل الواجهة قابلة للفهم لأشخاص وبيئات مختلفة.", "Contrast, heading order, clear button names, and keyboard operation help people in different situations understand the interface.") }, { heading: copy("أعد الفحص أثناء العمل", "Recheck while you work"), body: copy("اجعل مراجعة التركيز وتكبير الشاشة وتقليل الحركة جزءاً من كل مرحلة. الإصلاح المبكر أسهل من إعادة بناء المنتج في النهاية.", "Make focus, zoom, and reduced-motion checks part of every stage. Early adjustments are easier than rebuilding at the end.") }] },
  { slug: "color-as-navigation", topic: "visual-culture", title: copy("اللون طريق وليس زينة", "Color is a path, not decoration"), excerpt: copy("عندما يقود اللون، يجب أن تكون دلالته واضحة ومتسقة.", "When color guides people, its meaning should stay clear and consistent."), cover: portfolioImages.journalCulture, alt: copy("أشكال زرقاء ومرجانية على منصة معرض", "Blue and coral shapes on a gallery plinth"), readMinutes: 4, sections: [{ heading: copy("اربط اللون بدور", "Give color a role"), body: copy("حدد لوناً أساسياً للأفعال وألواناً ثانوية للحالات، ثم تحقق من دلالاتها في كل صفحة. النظام أهم من اختيار لون جميل مرة واحدة.", "Set a primary action color and supporting state colors, then check their meaning across every page. A system matters more than a single beautiful choice.") }, { heading: copy("لا تعتمد عليه وحده", "Do not rely on color alone"), body: copy("أضف نصاً أو رمزاً أو شكلاً يساعد على معرفة الحالة عندما لا يكفي اللون، خصوصاً في الإشارات التي يحتاج إليها الزائر لاتخاذ قرار.", "Add text, icons, or shape cues when color alone is insufficient, especially for signals people use to make a decision.") }] },
  { slug: "reading-visual-culture", topic: "visual-culture", title: copy("كيف نقرأ صورة؟", "How do we read an image?"), excerpt: copy("تكوين الصورة يوجه انتباهنا قبل أن نقرأ أول كلمة.", "Composition directs attention before we read the first word."), cover: portfolioImages.journalCulture, alt: copy("أشكال فنية وظلال حادة في مشهد تحريري", "Art forms and sharp shadows in an editorial still life"), readMinutes: 4, sections: [{ heading: copy("لاحظ مركز الثقل", "Notice the visual center"), body: copy("اسأل إلى أين ذهبت العين أولاً، وما الذي جعلها تتحرك بعد ذلك. الحجم والتباين والاتجاه تصنع مساراً حتى عندما لا توجد أسهم.", "Ask where the eye went first and what moved it next. Scale, contrast, and direction create a path even when there are no arrows.") }, { heading: copy("اترك مجالاً للسياق", "Leave room for context"), body: copy("الصورة ليست معناها وحدها؛ طريقة عرضها والنص المحيط بها يغيران القراءة. تأكد أن الأصول البصرية تخدم القصة ولا تحل محلها.", "An image is not its meaning alone; its presentation and surrounding copy change how it is read. Make sure visuals serve the story rather than replace it.") }] },
  { slug: "attention-before-decoration", topic: "visual-culture", title: copy("الانتباه قبل الزخرفة", "Attention before decoration"), excerpt: copy("قبل إضافة عنصر بصري جديد، اسأل: هل يساعد الزائر على فهم الفكرة أم ينافسها؟", "Before adding another visual element, ask whether it helps people understand the idea or competes with it."), cover: portfolioImages.journalCulture, alt: copy("تكوين تجريدي يوازن بين مساحة فارغة وكتل هندسية زرقاء", "An abstract composition balancing empty space with blue geometric forms"), readMinutes: 5, sections: [{ heading: copy("ارسم مسار النظر", "Map the visual path"), body: copy("ابدأ بتحديد أهم معلومة في الصفحة، ثم لاحظ ترتيب ما يأتي بعدها. التباين والمساحة والاتجاه أدوات لتوجيه الانتباه، وليست مبرراً لملء كل فراغ.", "Identify the most important information on the page, then decide what should follow. Contrast, space, and direction guide attention; they are not reasons to fill every gap.") }, { heading: copy("اترك القرار قابلاً للمراجعة", "Keep the decision reviewable"), body: copy("اختبر التصميم مع سياقه الفعلي ومع شاشة صغيرة. إذا احتاج العنصر إلى شرح طويل كي يبرر وجوده، فقد تكون البساطة خياراً أوضح.", "Test the design in its real context and on a small screen. If an element needs a long explanation to justify its presence, a simpler choice may be clearer.") }] },
];

