export function resolveStaticTitle(pathname: string, locale: Locale): Copy {
  const project = projects.find(item => pathname === `/work/${item.slug}`);
  if (project) return project.title;
  const service = services.find(item => pathname === `/services/${item.slug}`);
  if (service) return service.title;
  const article = articles.find(item => pathname === `/journal/${item.slug}`);
  if (article) return article.title;
  const info = infoPages[pathname];
  if (info) return info.title;
  const category = workCategories.find(item => pathname === `/work/${item.slug}`);
  if (category) return category.title;
  const topic = journalTopics.find(item => pathname === `/journal/topics/${item.slug}`);
  if (topic) return topic.title;
  const common: Record<string, Copy> = {
    "/": copy("الأرشيف الكبير للأفكار والتجارب", "A wide archive of ideas and experiments"),
    "/services": copy("خدمات إبداعية", "Creative services"),
    "/work": copy("مختارات من الأعمال", "Selected work"),
    "/journal": copy("دفتر الملاحظات", "The journal"),
    "/daily": copy("موجز اليوم", "Daily ideas"),
    "/github": copy("مستودعات GitHub العامة", "Public GitHub repositories"),
    "/ai-studio": copy("استوديو الذكاء الاصطناعي", "AI writing studio"),
    "/testimonials": copy("آراء العملاء", "Testimonials"),
    "/faq": copy("إجابات مختصرة", "Quick answers"),
    "/contact": copy("لنبدأ حواراً", "Start a conversation"),
  };
  return common[pathname] ?? copy("الأرشيف الكبير للأفكار والتجارب", "A wide archive of ideas and experiments");
}

export const categoryBySlug = (slug: string) => workCategories.find(item => item.slug === slug);
export const topicBySlug = (slug: string) => journalTopics.find(item => item.slug === slug);
export const projectBySlug = (slug: string) => projects.find(item => item.slug === slug);
export const serviceBySlug = (slug: string) => services.find(item => item.slug === slug);
export const articleBySlug = (slug: string) => articles.find(item => item.slug === slug);
